def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sep_r = next((r for r in range(h) if all(x == 2 for x in grid[r])), None)
    sep_c = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if sep_r is not None:
        side = list(range(sep_r + 1, h)) if sep_r < h // 2 else list(range(sep_r))
        vals = [grid[r][c] for r in side for c in range(w)]
        bg = Counter(vals).most_common(1)[0][0]
        points = [(r,c) for r in side for c in range(w) if grid[r][c] != bg]
        if points:
            if sep_r == 0:
                line = max(r for r,c in points) + 1
            else:
                line = min(r for r,c in points) - 2
            if 0 <= line < h: out[line] = [8] * w
    elif sep_c is not None:
        side = list(range(sep_c + 1, w)) if sep_c < w // 2 else list(range(sep_c))
        vals = [grid[r][c] for r in range(h) for c in side]
        bg = Counter(vals).most_common(1)[0][0]
        points = [(r,c) for r in range(h) for c in side if grid[r][c] != bg]
        if points:
            if sep_c == w - 1:
                line = min(c for r,c in points) - 1
            else:
                line = max(c for r,c in points) + 1
            if 0 <= line < w:
                for r in range(h): out[r][line] = 8
    return out

